        'MAXI_HLTH_UWR_VW_DATA_MEMBERS_MEMBER_DETAILS_MULTISET_ATTRIBUTE_ATTRIBUTES_PIVOT_VW' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
